    internal static int SptPrim(emon.Port.Cells prims, int kind, int cx, int cy, int rx, int ry, int ink, int rgb, int flags, int stroke) {
        int r = Evidence.PmNew(prims, 1, cx - rx, cy - ry, cx + rx, cy + ry, kind);
        Evidence.PmSet(prims, r, Evidence.PmfCx(), cx);
        Evidence.PmSet(prims, r, Evidence.PmfCy(), cy);
        Evidence.PmSet(prims, r, Evidence.PmfRx(), rx);
        Evidence.PmSet(prims, r, Evidence.PmfRy(), ry);
        Evidence.PmSet(prims, r, Evidence.PmfInk(), ink);
        Evidence.PmSet(prims, r, Evidence.PmfColor(), rgb);
        Evidence.PmSet(prims, r, Evidence.PmfConf(), 900);
        Evidence.PmSet(prims, r, Evidence.PmfFlags(), flags);
        Evidence.PmSet(prims, r, Evidence.PmfStroke(), stroke);
        return r;
    }
    internal static int SptInk(emon.Port.Cells inks, int role) {
        int r = Evidence.IkNew(inks, 1, 0);
        Evidence.IkSet(inks, r, Evidence.IkfRole(), role);
