    }
    [Xunit.Fact]
    public static void TestARingOrAStampOnTheRightLayerIsACandidate() {
        emon.Port.Cells views = emon.Port.NewCells();
        emon.Port.Cells prims = emon.Port.NewCells();
        emon.Port.Cells inks = emon.Port.NewCells();
        emon.Port.Cells cand = emon.Port.NewCells();
        Evidence.VwNew(views, 1, Evidence.VkRender(), -1, -1, 3000, 3000, 7200, 0, -1, 0, 0, 0, 0, 0);
        SptInk(inks, Evidence.IrBody());
        SptInk(inks, Evidence.IrLight());
        SptInk(inks, Evidence.IrColor());
        // a blue ring of radius 30 pt at (20 pt, 20 pt)... on the colour layer
        SptPrim(prims, Evidence.PmRing(), 20000, 20000, 3000, 3000, 2, 2047903, 4, 200);
        emon.Testport.AssertEq(Sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 1, "a ring on a colour layer: a candidate");
        emon.Testport.AssertEq(emon.Port.CellsAt(cand, 0), 1, "a seal");
        emon.Testport.AssertEq(emon.Port.CellsAt(cand, 2), 200, "its centre x in pixels (72 dpi: one a point)");
        emon.Testport.AssertEq(emon.Port.CellsAt(cand, 4), 30, "its radius");
        emon.Testport.AssertEq(emon.Port.CellsAt(cand, 13), 10, "its colour code: blue");
        // the ring of the page's body layer is one only as a double ring
        SptPrim(prims, Evidence.PmCircle(), 40000, 20000, 3000, 3000, 0, 1118481, 0, 200);
        emon.Testport.AssertEq(Sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 1, "a single circle on the body layer is a diagram's: still the one candidate");
        SptPrim(prims, Evidence.PmRing(), 40000, 40000, 3000, 3000, 0, 1118481, 4, 200);
        emon.Testport.AssertEq(Sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 2, "a double ring on the body layer is a seal");
        emon.Testport.AssertEq(emon.Port.CellsAt(cand, 13), 10, "(the colour one first)");
        emon.Testport.AssertEq(emon.Port.CellsAt(cand, 29), 0, "the body one is black");
        // a ring on a light layer (a watermark), a small ring: neither; an oblong curve of the colour layer (a rotated stamp's outline) is a stamp
        SptPrim(prims, Evidence.PmRing(), 20000, 60000, 3000, 3000, 1, 13487565, 4, 200);
        SptPrim(prims, Evidence.PmRing(), 20000, 60000, 1000, 1000, 2, 2047903, 4, 200);
        SptPrim(prims, Evidence.PmCurve(), 40000, 60000, 3000, 4500, 2, 2047903, 0, 200);
        emon.Testport.AssertEq(Sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 3, "the oblong curve is a stamp, the other two are no candidate");
        // a ring inside another, concentric: one candidate, the larger
        SptPrim(prims, Evidence.PmRing(), 20000, 20000, 2600, 2600, 2, 2047903, 0, 200);
        emon.Testport.AssertEq(Sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 3, "an inner ring is the seal's, not another");
        // a stamp: an outlined rectangle on the colour layer
        SptPrim(prims, Evidence.PmRect(), 30000, 70000, 5000, 2000, 2, 12591135, 1, 200);
        emon.Testport.AssertEq(Sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 4, "an outlined rectangle on the colour layer: a stamp");
        emon.Testport.AssertEq(emon.Port.CellsAt(cand, 48), 2, "a stamp");
        emon.Testport.AssertEq(emon.Port.CellsAt(cand, 52), 50, "half its width in pixels");
        emon.Testport.AssertEq(emon.Port.CellsAt(cand, 53), 20, "half its height");
    }
    [Xunit.Fact]
    public static void TestAColourBandAcrossThePageIsNoStamp() {
        emon.Port.Cells views = emon.Port.NewCells();
        emon.Port.Cells prims = emon.Port.NewCells();
        emon.Port.Cells inks = emon.Port.NewCells();
        emon.Port.Cells cand = emon.Port.NewCells();
        // D583 (smoke review A issue 16): an outlined colour rectangle most of the page's width (a heading's band holding its text) is not a stamp; the same size of rectangle
        // 100 pt wide is one
        Evidence.VwNew(views, 1, Evidence.VkRender(), -1, -1, 3000, 3000, 7200, 0, -1, 0, 0, 0, 0, 0);
        SptInk(inks, Evidence.IrBody());
        SptInk(inks, Evidence.IrLight());
        SptInk(inks, Evidence.IrColor());
        SptPrim(prims, Evidence.PmRect(), 30600, 70000, 25000, 1500, 2, 12591135, 1, 200);
        emon.Testport.AssertEq(Sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 0, "a band 500 pt wide on a page 612 pt wide: no candidate");
        SptPrim(prims, Evidence.PmRect(), 30000, 40000, 5000, 2000, 2, 12591135, 1, 200);
        emon.Testport.AssertEq(Sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 1, "a 100 pt rectangle is a stamp");
