        emon.Testport.AssertEq(Sealpx.SxDropLines(scr, 3, ol, ow, cand), 2, "the line in the ring is out; the line that runs from the ring across the page and the line elsewhere stay");
        emon.Testport.AssertEq(emon.Port.CellsAt(scr, Scan.ScSelBase()), 1, "the first left is the second line");
        emon.Testport.AssertEq(emon.Port.CellsAt(scr, Scan.ScSelBase() + 1), 2, "then the third");
        emon.Port.CellsSet(cand, 15, -1);
        emon.Port.CellsSet(scr, Scan.ScSelBase(), 0);
        emon.Port.CellsSet(scr, Scan.ScSelBase() + 1, 1);
        emon.Port.CellsSet(scr, Scan.ScSelBase() + 2, 2);
        emon.Testport.AssertEq(Sealpx.SxDropLines(scr, 3, ol, ow, cand), 3, "a candidate whose reading was not kept takes nothing out of the body");
    }
    [Xunit.Fact]
    public static void TestAStampsCropIsSizedForReading() {
        emon.Port.Cells cand = emon.Port.NewCells();
        while (emon.Port.CellsLen(cand) < 16) {
            emon.Port.CellsPush(cand, 0);
        }
        emon.Port.CellsSet(cand, 4, 100);
        emon.Port.CellsSet(cand, 5, 50);
        emon.Testport.AssertEq(Sealpx.SxStampDim(cand, 0, 0), 1500, "a stamp of 100 pixels high: the least scale, 1.5");
        emon.Testport.AssertEq(Sealpx.SxStampDim(cand, 0, 1), 316, "its width is 200 pixels at that scale and the margin");
        emon.Testport.AssertEq(Sealpx.SxStampDim(cand, 0, 2), 166, "its height 100");
        emon.Port.CellsSet(cand, 5, 20);
        emon.Testport.AssertEq(Sealpx.SxStampDim(cand, 0, 0), 3750, "a small one is enlarged until its height is 150: 3.75");
        emon.Port.CellsSet(cand, 4, 800);
        emon.Testport.AssertThat(Sealpx.SxStampDim(cand, 0, 1) <= 2000, "a wide one is kept under 2000 pixels");
    }
    [Xunit.Fact]
    public static void TestTheViewsAreAskedForByHashAndAskedAgainTheSame() {
        emon.Port.Cells views = emon.Port.NewCells();
        emon.Port.Cells prims = emon.Port.NewCells();
        emon.Port.Cells inks = emon.Port.NewCells();
        emon.Port.Cells cand = emon.Port.NewCells();
        emon.Port.Cells kp = emon.Port.NewCells();
        emon.Port.Cells tab = emon.Port.NewCells();
        emon.Port.Cells rq = emon.Port.NewCells();
        emon.Port.Cells rq2 = emon.Port.NewCells();
        emon.Port.Cells ans = emon.Port.NewCells();
        emon.Port.Cells loc = emon.Port.NewCells();
        emon.Port.BitmapSet bms = emon.Port.NewBitmapSet();
        emon.Port.BitmapSet bms2 = emon.Port.NewBitmapSet();
        emon.Port.Bitmap src = emon.Port.BitmapNew(240, 240, 3);
        SptFill(src, 255, 255, 255);
        SptBlock(src, 203, 118, 5, 5, 31, 63, 159);
        Evidence.VwNew(views, 1, Evidence.VkRender(), -1, -1, 240, 240, 7200, 0, -1, 0, 0, 0, 0, 0);
        SptInk(inks, Evidence.IrColor());
        SptPrim(prims, Evidence.PmRing(), 12000, 12000, 10000, 10000, 0, 2047903, 4, 200);
        emon.Testport.AssertEq(Sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 1, "the ring is a candidate");
        emon.Testport.AssertEq(Sealpx.SxPlan(0, loc, ans, bms, src, cand, kp, tab, rq), 2, "its strip and its centre are asked");
        emon.Testport.AssertThat(emon.Port.CellsLen(rq) > 0, "as requests");
        emon.Testport.AssertEq(emon.Port.BitmapW(emon.Port.BmsGet(bms, 16777216 + 48)), Sealpx.SxStripW(), "the strip is a view of the page's own set, at its id (2^24 + page * 256 + 48)");
        emon.Testport.AssertEq(emon.Port.BitmapH(emon.Port.BmsGet(bms, 16777216 + 48)), Sealpx.SxStripH(), "and `sx-strip-h` high");
        emon.Testport.AssertEq(emon.Port.BitmapW(emon.Port.BmsGet(bms, 16777216 + 49)), Sealpx.SxDiscN(), "the centre view is square");
        emon.Testport.AssertEq(Sealpx.SxPlan(0, loc, ans, bms2, src, cand, kp, tab, rq2), 2, "a re-run asks for the same two");
        emon.Testport.AssertEq(emon.Port.CellsLen(rq), emon.Port.CellsLen(rq2), "of the same length");
        emon.Testport.AssertThat(Sealpx.RiSeal() >= 128, "the request ids are in the crops' range");
        emon.Testport.AssertThat(Sealpx.SxW() >= 16, "and a record is at least 16 cells");
        emon.Testport.AssertThat(Sealpx.RvSeal() >= 48, "the views' ids come after the targeted passes'");
    }
